import networkx as nx,itertools

def chrom3(G):
 n=len(G)
 for c in itertools.product(range(3), repeat=n):
  if c[0]!=0: continue
  if all(c[u]!=c[v] for u,v in G.edges):return True
 return False

def prop(G, mode):
 n=len(G)
 for mask in range(1<<n):
  deg=[0]*n
  for u,v in G.edges:
   if (mask>>u&1)==(mask>>v&1):deg[u]+=1;deg[v]+=1
  if max(deg, default=0)>1:continue
  if mode==2 or not any(deg[v] and (mask>>v&1) for v in range(n)):return True
 return False
bad=[]
for G in nx.graph_atlas_g():
 if len(G)>7 or len(G)<1 or not nx.is_connected(G):continue
 if prop(G,2) and chrom3(G) and not prop(G,1):bad.append(G)
print('counterexamples',len(bad))
for G in bad[:5]: print(nx.to_graph6_bytes(G).decode().strip(),list(G.edges))

import networkx as nx,itertools,collections

def costs(G,r=3):
 n=len(G); adj=[sum(1<<v for v in G[u]) for u in range(n)]
 masks=[0]*r; best=99; witness=None
 def rec(v,used):
  nonlocal best,witness
  if v==n:
   cost=sum(any(adj[u]&m for u in range(n) if m>>u&1) for m in masks)
   if cost<best:best=cost;witness=masks.copy()
   return
  for c in range(min(used+1,r)):
   m=masks[c];nei=adj[v]&m
   if nei.bit_count()>1:continue
   if nei:
    u=nei.bit_length()-1
    if adj[u]&m:continue
   masks[c]|=1<<v;rec(v+1,max(used,c+1));masks[c]=m
 rec(0,0);return best,witness
found=[]
for G in nx.graph_atlas_g():
 if len(G)<4 or not nx.is_connected(G):continue
 b,w=costs(G)
 if b==3:
  print('FOUND',len(G),G.number_of_edges(),list(G.edges()),w); found.append(G)
print('count',len(found))

